    <div class="grid grid-4 mb16">${U.kpi({ label: 'Hôm nay', value: all.filter(v => v.status === 'scheduled' && v.date === F.today()).length, cap: 'Lịch hẹn trong ngày', icon: 'calendar', tone: 'blue' })}${U.kpi({ label: 'Sắp tới (7 ngày)', value: all.filter(v => v.status === 'scheduled' && F.daysUntil(v.date) >= 0 && F.daysUntil(v.date) <= 7).length, cap: 'Cần nhắc lịch', icon: 'bell', tone: 'amber' })}${U.kpi({ label: 'Đã xem tháng này', value: all.filter(v => v.status === 'done' && F.period(v.date) === St.state.meta.period).length, cap: 'Quan tâm: ' + all.filter(v => v.status === 'done' && v.result === 'interested').length, icon: 'check-circle', tone: 'green' })}${U.kpi({ label: 'Hủy / Không đến', value: cnt('cancelled') + cnt('no_show'), cap: 'Tỷ lệ ' + F.pct(cnt('cancelled') + cnt('no_show'), all.length) + '%', icon: 'x-circle', tone: 'red' })}</div>
