    const tbl = U.table(root.querySelector('#vt'), { rows, unit: 'lịch', selectable: true, selectableIf: v => v.status === 'scheduled', colPrefsKey: 'viewings', cols: [{ key: 'code', label: 'Mã', render: v => `<b>${esc(v.code)}</b>` }, { key: 'dt', label: 'Ngày giờ', sortable: true, sortVal: v => v.date + v.time, render: v => `<b>${F.date(v.date)}</b> ${esc(v.time)}` }, { key: 'lead', label: 'Lead', render: v => U.cell2(U.link('#/crm/leads/' + v.leadId, esc(Q.lead(v.leadId).name)), esc(Q.lead(v.leadId).phone)) }, { key: 'room', label: 'Phòng', render: v => U.link('#/rooms/' + v.roomId, esc(Q.room(v.roomId).code || '-')) }, { key: 'b', label: 'Tòa', render: v => esc(bName(v.buildingId)) }, { key: 'sale', label: 'Nhân viên', render: v => esc(Q.userName(v.saleId)) }, { key: 'remind', label: 'Nhắc hẹn', render: v => v.reminded ? U.chip('Đã nhắc ' + F.date(v.reminded.slice(0, 10)), 'green') : esc(v.remind || '-') }, { key: 'status', label: 'Trạng thái', sortable: true, render: v => Q.chip('viewing', v.status) + (v.result ? ' ' + Q.chip('viewingResult', v.result) : '') }, { key: 'actions', label: 'Thao tác', render: v => U.rowActions([v.status === 'scheduled' ? U.actBtn({ icon: 'check', label: 'Ghi kết quả', act: 'result', attrs: { 'data-id': v.id }, tone: 'success' }) : '', U.moreBtn(v.id)]), hideable: false }] });
