  const leadListHtml = (w, act = 'pick-lead') => { const s = w.leadSearch || ''; const leads = St.where('leads', l => Q.leadOnBoard(l) && (!s || F.norm(l.name + ' ' + l.phone + ' ' + l.code).includes(F.norm(s)))).sort((a, b) => F.cmp(b.updatedAt, a.updatedAt)).slice(0, 12); return leads.map(l => `<div class="it" style="cursor:pointer;${w.leadId === l.id ? 'background:var(--primary-50);border-radius:8px;padding:8px' : ''}" data-act="${act}" data-id="${l.id}">${U.avatar(l.name)}<div class="grow"><b>${esc(l.name)}</b><small>${esc(l.phone)} · ${esc(Q.leadSource(l.sourceId).name || '')} · ${esc((l.buildingIds || []).map(bName).join(', '))}</small></div>${Q.chip('lead', l.status)}${priorityIndicator(l.temp)}</div>`).join('') || '<div class="muted small">Không có lead</div>'; };
