    const w = wz('viewing', q, { date: F.addDays(F.today(), 1), time: '10:00', saleId: '', remind: 'Gửi Zalo + Email', place: '', note: '' });
    const l = w.leadId ? St.get('leads', w.leadId) : null; const r = w.roomId ? St.get('rooms', w.roomId) : null; if (l && !w.saleId) w.saleId = l.saleId; if (r && !w.place) w.place = bName(r.buildingId) + ' - Sảnh lễ tân';
    const step = !l ? 1 : !r ? 2 : Math.max(3, w.step);
    const STEPS = [{ title: 'Chọn lead', sub: 'Tìm và chọn khách hàng' }, { title: 'Chọn phòng', sub: 'Chọn phòng muốn xem' }, { title: 'Lịch hẹn', sub: 'Thiết lập thời gian và nhân sự' }, { title: 'Xác nhận', sub: 'Kiểm tra và hoàn tất' }];
    const summary = () => U.card({ title: 'Tóm tắt lịch xem', icon: 'file-text', body: `<div class="bold mb8 row between"><span>${I('user')} Thông tin khách hàng</span>${l ? `<a class="link small" data-act="to1">Chỉnh sửa</a>` : ''}</div>${l ? `<div class="row gap12 mb8">${U.avatar(l.name)}<div><b>${esc(l.name)}</b><div class="small muted">${I('phone')} ${esc(l.phone)}<br>${I('mail')} ${esc(l.email || '-')}</div></div></div>${U.kv([['Nhu cầu', `<span class="chip blue">${esc(l.roomType || '-')}, ngân sách ${F.short(l.budgetMin)}-${F.short(l.budgetMax)}</span>`], ['Nguồn lead', `<span class="chip green">${esc(Q.leadSource(l.sourceId).name || '')}</span>`]], 'one')}` : '<div class="muted small">Chưa chọn lead</div>'}<hr class="mt12 mb12"><div class="bold mb8 row between"><span>${I('home')} Thông tin phòng</span>${r ? `<a class="link small" data-act="to2">Chỉnh sửa</a>` : ''}</div>${r ? `<div class="row gap12"><div class="room-img" style="width:90px;flex:none"></div><div><b>${esc(r.code)}</b><div class="small muted">${esc(bName(r.buildingId))}<br>${esc(r.type)} · ${r.area} m²</div><b class="blue">${F.vnd(r.price)} đ/tháng</b><div>${U.chip('Trống', 'green', true)}</div></div></div>` : '<div class="muted small">Chưa chọn phòng</div>'}<hr class="mt12 mb12"><div class="bold mb8">${I('calendar')} Thông tin lịch hẹn</div>${U.kv([['Ngày hẹn', F.date(w.date)], ['Giờ hẹn', esc(w.time)], ['Địa điểm gặp', esc(w.place || '-')], ['Nhân viên phụ trách', esc(Q.userName(w.saleId))], ['Nhắc hẹn', esc(w.remind)]], 'one')}` });
    let main = '';
    if (step === 1) main = leadPick(w);
    else if (step === 2) main = leadCardSm(l, 'to1') + '<div class="mt16">' + roomPick(w, l, { allowHeld: true }) + '</div>';
    else { const hist = Q.leadViewings(l.id).filter(v => !v._new).slice(0, 5);
      main = `<div class="grid grid-2">${leadCardSm(l, 'to1')}${roomCardSm(r, 'to2')}</div><form id="vf">${U.card({ title: 'Thông tin lịch hẹn', icon: 'calendar', cls: 'mt16', body: `<div class="form-grid">${U.field({ label: 'Ngày hẹn', req: true, input: U.date({ name: 'date', value: w.date, attrs: { min: F.today() } }) })}${U.field({ label: 'Giờ hẹn', req: true, input: U.select({ name: 'time', value: w.time, options: ['08:00', '09:00', '10:00', '11:00', '14:00', '15:00', '16:00', '17:00', '18:00'] }) })}${U.field({ label: 'Nhân viên phụ trách', req: true, input: U.select({ name: 'saleId', value: w.saleId, placeholder: 'Chọn nhân viên', options: Q.salesUsers().concat(St.where('users', u => u.role === 'ops' && u.status === 'active')).map(u => [u.id, u.name + ' – ' + TH.auth.ROLE_LABEL[u.role]]) }) })}${U.field({ label: 'Phương thức nhắc hẹn', req: true, input: U.select({ name: 'remind', value: w.remind, options: ['Gửi Zalo + Email', 'Gửi Zalo', 'Gửi Email', 'Gọi điện', 'Không nhắc'] }), help: I('map-pin') + ' Hệ thống sẽ tự động gửi nhắc hẹn cho khách hàng' })}${U.field({ label: 'Địa điểm gặp', req: true, input: U.select({ name: 'place', value: w.place, options: [bName(r.buildingId) + ' - Sảnh lễ tân', bName(r.buildingId) + ' - Phòng ' + r.code, 'Văn phòng TimoHouse'] }), help: I('map-pin') + ' Địa chỉ: ' + esc(Q.building(r.buildingId).address || '') })}${U.field({ label: 'Ghi chú', input: U.textarea({ name: 'note', value: w.note, placeholder: 'Khách quan tâm view thoáng…', attrs: { maxlength: 500 } }), help: '<span class="tr" style="display:block">' + (w.note || '').length + '/500</span>' })}</div>` })}</form>
      ${U.card({ title: 'Lịch xem gần nhất của khách hàng', icon: 'clock', cls: 'mt16', bodyCls: 'tight', body: `<table class="tbl compact"><thead><tr><th>#</th><th>Ngày hẹn</th><th>Phòng</th><th>Tòa nhà</th><th>Nhân viên phụ trách</th><th>Trạng thái</th><th>Ghi chú</th></tr></thead><tbody>${hist.map((v, i) => `<tr><td>${i + 1}</td><td>${F.date(v.date)} ${esc(v.time)}</td><td>${U.link('#/rooms/' + v.roomId, esc(Q.room(v.roomId).code))}</td><td>${esc(bName(v.buildingId))}</td><td>${esc(Q.userName(v.saleId))}</td><td>${Q.chip('viewing', v.status)}</td><td class="small">${esc(v.resultNote || v.note || '')}</td></tr>`).join('') || '<tr><td colspan="7" class="muted tc">Khách chưa có lịch xem trước đó</td></tr>'}</tbody></table>` })}`; }
    root.innerHTML = `${U.pageHead(Object.assign({ title: 'Đặt lịch xem phòng', sub: 'Tạo lịch hẹn xem phòng cho lead và điều phối nhân viên phụ trách.' }, PH))}${U.wizard(STEPS, step - 1)}<div class="two-col wide"><div class="side-stack">${main}</div><aside class="side-stack">${summary()}</aside></div>
    <div class="wz-foot mt16">${U.btn({ label: 'Quay lại', icon: 'arrow-left', cls: 'btn-outline', act: 'back' })}<div class="row">${U.btn({ label: 'Lưu nháp', icon: 'save', cls: 'btn-outline', act: 'draft' })}${U.btn({ label: 'Xác nhận lịch xem', icon: 'arrow-right', cls: 'btn-primary', act: 'confirm', disabled: step < 3, attrs: { 'data-guide': 'viewing-confirm' } })}</div></div>`;
    const readForm = () => { const f = root.querySelector('#vf'); if (f) Object.assign(w, U.formData(f)); w.touched = true; };
    root.addEventListener('input', (e) => { if (e.target.name === 'note') { const c = root.querySelector('#vf .help .tr'); if (c) c.textContent = e.target.value.length + '/500'; } });
    U.onChange(root, { 'room-building': (el) => { w.roomBuilding = el.value; TH.router.refresh(); } });
    bindLeadSearch(root, w);
    U.bind(root, { 'pick-lead': (el) => { w.leadId = el.dataset.id; w.saleId = ''; w.touched = true; TH.router.refresh(); }, 'pick-room': (el) => { w.roomId = el.dataset.id; w.place = ''; w.step = 3; w.touched = true; TH.router.refresh(); }, to1: () => { readForm(); w.leadId = ''; w.roomId = ''; TH.router.refresh(); }, to2: () => { readForm(); w.roomId = ''; TH.router.refresh(); }, back: () => { if (step === 1) { delete TH._wz.viewing; return history.back(); } readForm(); if (step === 2) w.leadId = ''; else w.roomId = ''; TH.router.refresh(); },
      draft: () => { readForm(); St.state.meta.drafts = St.state.meta.drafts || {}; St.state.meta.drafts.viewing = Object.assign({}, w); St.save(); ok('Đã lưu nháp lịch xem', 'Tiếp tục khi quay lại trang'); },
      confirm: async () => { readForm(); try { const v = X.saveViewing({ leadId: w.leadId, roomId: w.roomId, date: w.date, time: w.time, saleId: w.saleId, remind: w.remind, place: w.place, note: w.note }); delete TH._wz.viewing; ok('Đã tạo lịch xem ' + v.code, F.date(v.date) + ' ' + v.time + ' – ' + Q.room(v.roomId).code); TH.go('#/crm/leads/' + v.leadId + '?tab=viewings'); } catch (e) { if (e.code === 'CLASH') { if (await U.confirm({ title: 'Trùng giờ', text: esc(e.message) + '. Vẫn đặt lịch?', ok: 'Vẫn đặt' })) { const v = X.saveViewing({ leadId: w.leadId, roomId: w.roomId, date: w.date, time: w.time, saleId: w.saleId, remind: w.remind, place: w.place, note: w.note, force: true }); delete TH._wz.viewing; ok('Đã tạo lịch xem ' + v.code); TH.go('#/crm/leads/' + v.leadId + '?tab=viewings'); } } else throw e; } } });
