  TH.router.register('/crm/holds', (root, p, q) => {
    TH.router.crumb([{ label: 'Kinh doanh' }, { label: 'Giữ chỗ' }]);
    const f = { status: q.status || '', s: q.s || '' }; const all = St.all('holds').map(h => Object.assign({}, h, { st: Q.holdStatus(h) }));
    const rows = all.filter(h => (!f.status || h.st === f.status) && (!f.s || F.norm((h.code || '') + ' ' + Q.tenant(h.tenantId).name + ' ' + Q.room(h.roomId).code).includes(F.norm(f.s)))).sort((a, b) => F.cmp(b.createdAt, a.createdAt));
    const cnt = (k) => all.filter(h => h.st === k).length; const expToday = all.filter(h => h.st === 'active' && (h.until || h.expiresAt) === F.today()).length;
    root.innerHTML = `${U.pageHead(Object.assign({ title: 'Giữ chỗ phòng', sub: 'Giữ chỗ tối đa 14 ngày, phí giữ chỗ trừ vào cọc khi ký hợp đồng; hết hạn tự mở phòng (OI-09).', acts: [U.btn({ label: 'Tạo giữ chỗ', icon: 'plus', cls: 'btn-primary', act: 'add', disabled: !TH.auth.can('holds.manage') })] }, PH))}
    <div class="grid grid-4 mb16">${U.kpi({ label: 'Đang giữ', value: cnt('active'), cap: 'Phòng đang khóa khỏi danh sách', icon: 'clock', tone: 'amber' })}${U.kpi({ label: 'Hết hạn hôm nay', value: expToday, cap: 'Tự mở phòng lúc 23:59', icon: 'timer', tone: 'red' })}${U.kpi({ label: 'Đã chuyển đổi', value: cnt('converted'), cap: 'Thành hợp đồng', icon: 'check-circle', tone: 'green' })}${U.kpi({ label: 'Hết hạn / Đã hủy', value: cnt('expired') + cnt('cancelled'), cap: 'Phòng đã mở lại', icon: 'x-circle', tone: 'gray' })}</div>
    ${U.statusTabs([{ key: '', label: 'Tất cả', count: all.length }, { key: 'active', label: 'Đang giữ', count: cnt('active'), color: 'amber' }, { key: 'converted', label: 'Đã chuyển đổi', count: cnt('converted'), color: 'green' }, { key: 'expired', label: 'Hết hạn', count: cnt('expired'), color: 'gray' }, { key: 'cancelled', label: 'Đã hủy', count: cnt('cancelled'), color: 'red' }], f.status)}
    ${U.card({ title: 'Danh sách giữ chỗ', actions: U.input({ name: 's', value: f.s, placeholder: 'Tìm mã, khách, phòng…', icon: 'search', cls: 'sm', attrs: { id: 'hs', style: 'width:240px' } }), body: null, id: 'ht' })}`;
    U.table(root.querySelector('#ht'), { rows, unit: 'giữ chỗ', cols: [{ key: 'code', label: 'Mã', render: h => `<b>${esc(h.code || '-')}</b>` }, { key: 'lead', label: 'Lead / Khách', render: h => h.leadId ? U.cell2(U.link('#/crm/leads/' + h.leadId, esc(Q.lead(h.leadId).name)), esc(Q.tenant(h.tenantId).name || '')) : U.link('#/tenants/' + h.tenantId, esc(Q.tenant(h.tenantId).name || '-')) }, { key: 'room', label: 'Phòng', render: h => U.cell2(U.link('#/rooms/' + h.roomId, esc(Q.room(h.roomId).code || '-')), esc(bName(Q.room(h.roomId).buildingId))) }, { key: 'period', label: 'Từ – Đến', render: h => F.date(h.start || h.createdAt) + ' – ' + F.date(h.until || h.expiresAt) }, { key: 'left', label: 'Còn lại', sortable: true, sortVal: h => Q.holdDaysLeft(h), render: h => h.st === 'active' ? `<span class="${Q.holdDaysLeft(h) <= 2 ? 'red bold' : ''}">${Q.holdDaysLeft(h)} ngày</span>` : '-' }, { key: 'fee', label: 'Phí giữ chỗ', num: true, render: h => F.vnd(h.fee || h.deposit || 0) }, { key: 'by', label: 'Thu bởi', render: h => esc(Q.userName(h.receiverId || h.createdBy)) }, { key: 'st', label: 'Trạng thái', sortable: true, render: h => Q.chip('hold', h.st) }, { key: 'actions', label: 'Thao tác', render: h => U.rowActions([h.st === 'active' && h.leadId ? U.actBtn({ icon: 'check-square', label: 'Chốt thuê', act: 'deal', attrs: { 'data-id': h.leadId }, tone: 'primary' }) : '', U.moreBtn(h.id)]), hideable: false }] });
    root.querySelector('#hs').addEventListener('keydown', e => { if (e.key === 'Enter') { TH.router.replaceQuery(Object.assign({}, f, { s: e.target.value })); TH.router.refresh(); } });
    U.bind(root, { stab: (el) => { TH.router.replaceQuery(Object.assign({}, f, { status: el.dataset.key })); TH.router.refresh(); }, add: () => TH.go('#/crm/holds/new'), deal: (el) => TH.go('#/crm/deals/new?lead=' + el.dataset.id), more: (el) => { const h = St.get('holds', el.dataset.id); const st = Q.holdStatus(h); U.menu(el, [{ label: 'Xem phòng', icon: 'door', onClick: () => TH.go('#/rooms/' + h.roomId) }, h.leadId ? { label: 'Xem lead', icon: 'user', onClick: () => TH.go('#/crm/leads/' + h.leadId) } : { label: 'Xem khách', icon: 'user', onClick: () => TH.go('#/tenants/' + h.tenantId) }, '-', { label: 'Gia hạn', icon: 'calendar', disabled: st !== 'active', onClick: async () => { const r = await U.confirm({ title: 'Gia hạn giữ chỗ ' + (h.code || ''), body: U.field({ label: 'Giữ đến ngày (tối đa 14 ngày từ ngày bắt đầu)', input: U.date({ name: 'until', value: F.addDays(h.until || h.expiresAt, 3) }) }), ok: 'Gia hạn' }); if (r) { X.extendHold(h.id, r.until); ok('Đã gia hạn'); } } }, { label: 'Chốt thuê', icon: 'check-square', disabled: st !== 'active' || !h.leadId, onClick: () => TH.go('#/crm/deals/new?lead=' + h.leadId) }, { label: 'Hủy giữ chỗ', icon: 'x-circle', danger: true, disabled: st !== 'active', onClick: async () => { const r = await U.confirm({ title: 'Hủy giữ chỗ ' + (h.code || '') + '?', text: 'Điều kiện hủy: ' + ({ forfeit: 'Mất phí giữ chỗ', refund: 'Hoàn phí', partial: 'Hoàn một phần' }[h.cancelPolicy] || 'Mất phí') + '. Phòng trở về Sẵn sàng.', body: U.field({ label: 'Lý do', input: U.input({ name: 'reason' }) }), ok: 'Hủy giữ chỗ', danger: true }); if (r) { X.cancelHoldP2(h.id, { reason: r.reason, refund: h.cancelPolicy === 'refund' }); ok('Đã hủy giữ chỗ'); } } }]); } });
  }, { menu: 'holds', permission: 'crm.view', phase: 2, scopeKey: 'holds' });

